pre-commit:
  parallel: false
  commands:
    format:
      glob: '*.{ts,js,svelte,md,json,yaml,yml,css,html}'
      run: VOLTA_FEATURE_PNPM=1 pnpm exec prettier --write --ignore-unknown {staged_files}
      stage_fixed: true
    lint:
      run: make lint
    actionlint:
      glob: '.github/workflows/*.{yml,yaml}'
      run: actionlint {staged_files}
    scan-secrets:
      run: make secret-scan

commit-msg:
  commands:
    commitlint:
      priority: 1
      run: VOLTA_FEATURE_PNPM=1 pnpm exec commitlint --edit {1}
    # lefthook install replaces Entire's hook wrappers, so Entire is chained here instead.
    entire:
      priority: 2
      run: if command -v entire >/dev/null 2>&1; then entire hooks git commit-msg {1} || true; fi

pre-push:
  parallel: false
  commands:
    typecheck:
      run: make typecheck
    unit-tests:
      run: make test
    e2e:
      run: make e2e
    entire:
      run: if command -v entire >/dev/null 2>&1; then entire hooks git pre-push {1} || true; fi
