blocked.addAddress('::1', 'ipv6');
blocked.addSubnet('fe80::', 10, 'ipv6');
blocked.addSubnet('fc00::', 7, 'ipv6');

/**
 * Rejects hosts that resolve to loopback, private, link-local, CGNAT or unspecified addresses.
 * @param hostname URL hostname.
 * @returns True when every resolved address is public.
 */
async function isPublicHost(hostname: string): Promise<boolean> {
	const host = hostname.replace(/^\[|\]$/g, '');
	const family = isIP(host);
	const addresses = family
		? [{ address: host, family }]
		: await lookup(host, { all: true }).catch(() => []);
	return (
		addresses.length > 0 &&
		addresses.every((a) => !blocked.check(a.address, a.family === 6 ? 'ipv6' : 'ipv4'))
	);
}

